package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.accessories.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.client.gui.inventory.*;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.entity.player.*;import net.minecraft.item.*;import net.minecraft.init.Blocks;import net.minecraft.potion.Potion;import net.minecraft.util.ScreenShotHelper;import org.lwjgl.opengl.GL11;
import codechicken.nei.recipe.*;
public final class AccessoryClientChecks {
 private List<String> results=new ArrayList<String>();private int phase,wait=30,tries,recipe;private boolean done;private volatile Throwable failure;
 public void init(){FMLCommonHandler.instance().bus().register(this);}static void check(boolean b,String why){if(!b)throw new AssertionError(why);}void pass(String s){results.add("PASS: "+s);IndustrialTechnology.log.info("ACCESSORY CLIENT PASS: "+s);}
 static WorldServer world(){return MinecraftServer.getServer().worldServerForDimension(0);}static EntityPlayerMP player(){return(EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
 void server(Runnable r){ServerWork.enqueue(()->{try{r.run();}catch(Throwable e){failure=e;IndustrialTechnology.log.error("Accessory GUI server",e);}});}
 void shot(Minecraft mc,String name){check(GL11.glGetError()==0,"OpenGL error");ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
 void click(Minecraft mc,int slot){mc.playerController.windowClick(mc.thePlayer.openContainer.windowId,slot,0,0,mc.thePlayer);}
 Item item(int i){return new Item[]{AccessoryRegistry.flightRing,AccessoryRegistry.nightAmulet,AccessoryRegistry.catalyst,AccessoryRegistry.hyperLens,AccessoryRegistry.catalyticLens}[i];}
 void openRecipe(Minecraft mc){mc.thePlayer.closeScreen();check(GuiCraftingRecipe.openRecipeGui("item",new ItemStack(item(recipe))),"Missing NEI recipe "+recipe);}
 @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
  if(failure!=null)throw new AssertionError("Server-side GUI check",failure);
  if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(210,WorldSettings.GameType.SURVIVAL,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("accessories-gui","Disposable accessories QA",s);phase=1;wait=70;return;}
  if(mc.thePlayer==null||mc.theWorld==null){check(++tries<100,"Join timeout");wait=10;return;}
  if(phase==1){mc.displayGuiScreen(null);server(()->{WorldServer w=world();for(int x=16;x<30;x++)for(int z=16;z<30;z++)w.setBlock(x,69,z,Blocks.stone,0,3);EntityPlayerMP p=player();p.setPositionAndUpdate(22.5,70,22.5);p.inventory.setInventorySlotContents(9,new ItemStack(AccessoryRegistry.flightRing));p.inventory.setInventorySlotContents(10,new ItemStack(AccessoryRegistry.nightAmulet));for(int i=0;i<3;i++)p.inventory.setInventorySlotContents(i,new ItemStack(item(i+2)));p.inventory.setInventorySlotContents(8,new ItemStack(net.minecraft.init.Items.coal,32));p.inventoryContainer.detectAndSendChanges();});phase=2;wait=40;return;}
  if(phase==2){mc.displayGuiScreen(new GuiInventory(mc.thePlayer));phase=3;wait=25;return;}
  if(phase==3){Field f=GuiScreen.class.getDeclaredField("buttonList");f.setAccessible(true);GuiButton button=null;for(Object o:(List)f.get(mc.currentScreen))if(((GuiButton)o).id==55)button=(GuiButton)o;check(button!=null,"Original gold-ring Baubles button absent");shot(mc,"accessories-baubles-button.png");Method m=GuiScreen.class.getDeclaredMethod("mouseClicked",int.class,int.class,int.class);m.setAccessible(true);m.invoke(mc.currentScreen,button.xPosition+3,button.yPosition+3,0);phase=4;wait=30;return;}
  if(phase==4){check(mc.currentScreen!=null&&mc.currentScreen.getClass().getName().equals("baubles.client.gui.GuiPlayerExpanded"),"Original Baubles UI did not open: "+mc.currentScreen);pass("Original gold-ring inventory button opens the real Baubles equipment screen");click(mc,13);click(mc,10);click(mc,14);click(mc,9);phase=5;wait=40;return;}
  if(phase==5){check(mc.thePlayer.openContainer.getSlot(10).getStack()!=null&&mc.thePlayer.openContainer.getSlot(10).getStack().getItem()==AccessoryRegistry.flightRing,"Ring slot");check(mc.thePlayer.capabilities.allowFlying&&mc.thePlayer.isPotionActive(Potion.nightVision),"Flight/nightvision did not sync");shot(mc,"accessories-equipped.png");pass("Vanilla inventory clicks equip our ring/amulet and synchronize flight/nightvision from the server");click(mc,10);click(mc,13);click(mc,9);click(mc,14);phase=6;wait=40;return;}
  if(phase==6){check(!mc.thePlayer.capabilities.allowFlying&&!mc.thePlayer.isPotionActive(Potion.nightVision),"Unequip effects stayed active");pass("Removing both accessories through the real equipment screen removes their effects");mc.thePlayer.closeScreen();phase=7;wait=15;return;}
  if(phase==7){mc.thePlayer.inventory.currentItem=0;IndustrialTechnology.network.sendToServer(new AccessoryCommand(0,0));phase=8;wait=15;return;}
  if(phase==8){check(((ItemCatalyst)mc.thePlayer.getHeldItem().getItem()).charge(mc.thePlayer.getHeldItem())==1,"Charge packet not synchronized");pass("Actual client/server charge packet updates the held tool and synchronizes its NBT");IndustrialTechnology.network.sendToServer(new AccessoryCommand(0,1));phase=9;wait=15;return;}
  if(phase==9){check(((ItemCatalyst)mc.thePlayer.getHeldItem().getItem()).charge(mc.thePlayer.getHeldItem())==1,"Stale slot packet accepted");pass("Server rejects a charge packet naming a different hotbar slot");openRecipe(mc);phase=10;wait=25;return;}
  if(phase==10){check(mc.currentScreen instanceof GuiCraftingRecipe,"NEI recipe screen missing");GuiRecipe gui=(GuiRecipe)mc.currentScreen;boolean found=false;for(IRecipeHandler h:gui.getCurrentRecipeHandlers())for(int i=0;i<h.numRecipes();i++)if(h.getResultStack(i)!=null&&h.getResultStack(i).item.getItem()==item(recipe))found=true;check(found,"NEI result missing "+recipe);shot(mc,"accessories-recipe-"+recipe+".png");pass("NEI displays the standalone "+new ItemStack(item(recipe)).getDisplayName()+" recipe and original icon");if(++recipe<5){openRecipe(mc);wait=25;return;}mc.thePlayer.closeScreen();phase=11;wait=20;return;}
  if(phase==11){results.add("INFO: original mods present="+Loader.isModLoaded("ProjectE")+","+Loader.isModLoaded("baublelicious"));check(mc.getIntegratedServer().shareToLAN(WorldSettings.GameType.SURVIVAL,false)!=null,"LAN open failed");check(mc.getIntegratedServer().getPublic(),"Not a LAN session");pass("Disposable Survival world opens to LAN before exercising real right-click packets");mc.thePlayer.inventory.currentItem=0;server(()->{EntityPlayerMP p=player();baubles.common.container.InventoryBaubles inv=baubles.common.lib.PlayerHandler.getPlayerBaubles(p);for(int i=0;i<4;i++)inv.setInventorySlotContents(i,null);ItemStack held=new ItemStack(AccessoryRegistry.nightAmulet);held.setStackDisplayName("LAN right-click amulet");p.inventory.setInventorySlotContents(0,held);p.sendContainerToPlayer(p.inventoryContainer);});phase=12;wait=40;return;}
  if(phase==12){check(!mc.thePlayer.capabilities.isCreativeMode&&mc.thePlayer.getHeldItem().getItem()==AccessoryRegistry.nightAmulet,"Survival held amulet missing");mc.playerController.sendUseItem(mc.thePlayer,mc.theWorld,mc.thePlayer.getHeldItem());phase=13;wait=40;return;}
  if(phase==13){check(mc.thePlayer.getHeldItem()==null&&mc.thePlayer.isPotionActive(Potion.nightVision),"Right-click amulet consumption/effect did not sync");pass("Actual LAN right-click packet equips the amulet, consumes the Survival held item and synchronizes nightvision without crashing");shot(mc,"accessories-lan-right-click.png");server(()->{EntityPlayerMP p=player();ItemStack worn=baubles.common.lib.PlayerHandler.getPlayerBaubles(p).getStackInSlot(0);check(worn.stackSize==1&&worn.getDisplayName().equals("LAN right-click amulet")&&p.getHeldItem()==null,"Server amulet/NBT/held state");p.inventory.setInventorySlotContents(0,new ItemStack(AccessoryRegistry.flightRing));p.sendContainerToPlayer(p.inventoryContainer);});phase=14;wait=40;return;}
  if(phase==14){check(mc.thePlayer.getHeldItem().getItem()==AccessoryRegistry.flightRing,"Held ring missing");mc.playerController.sendUseItem(mc.thePlayer,mc.theWorld,mc.thePlayer.getHeldItem());phase=15;wait=40;return;}
  if(phase==15){check(mc.thePlayer.getHeldItem()==null&&mc.thePlayer.capabilities.allowFlying,"First ring consumption/flight did not sync");pass("Actual LAN right-click packet equips the flight ring and synchronizes Survival flight");server(()->{EntityPlayerMP p=player();check(baubles.common.lib.PlayerHandler.getPlayerBaubles(p).getStackInSlot(1).stackSize==1,"First ring slot missing");p.inventory.setInventorySlotContents(0,new ItemStack(AccessoryRegistry.flightRing));p.sendContainerToPlayer(p.inventoryContainer);});phase=16;wait=40;return;}
  if(phase==16){mc.playerController.sendUseItem(mc.thePlayer,mc.theWorld,mc.thePlayer.getHeldItem());phase=17;wait=40;return;}
  if(phase==17){check(mc.thePlayer.getHeldItem()==null&&mc.thePlayer.capabilities.allowFlying,"Second ring consumption/flight");pass("A second right-click ring equips without losing flight or duplicating the held item");server(()->{EntityPlayerMP p=player();check(baubles.common.lib.PlayerHandler.getPlayerBaubles(p).getStackInSlot(2).stackSize==1,"Second ring slot missing");p.inventory.setInventorySlotContents(0,new ItemStack(AccessoryRegistry.flightRing));p.sendContainerToPlayer(p.inventoryContainer);});phase=18;wait=40;return;}
  if(phase==18){mc.playerController.sendUseItem(mc.thePlayer,mc.theWorld,mc.thePlayer.getHeldItem());phase=19;wait=40;return;}
  if(phase==19){check(mc.thePlayer.getHeldItem()!=null&&mc.thePlayer.getHeldItem().stackSize==1,"Full ring slots lost held ring");pass("Right-clicking with both ring slots occupied retains the held ring");server(()->{EntityPlayerMP p=player();check(p.getHeldItem().stackSize==1,"Server lost third ring");p.inventory.setInventorySlotContents(0,new ItemStack(AccessoryRegistry.nightAmulet));p.sendContainerToPlayer(p.inventoryContainer);});phase=20;wait=40;return;}
  if(phase==20){mc.playerController.sendUseItem(mc.thePlayer,mc.theWorld,mc.thePlayer.getHeldItem());phase=21;wait=40;return;}
  if(phase==21){check(mc.thePlayer.getHeldItem()!=null&&mc.thePlayer.getHeldItem().stackSize==1&&mc.thePlayer.isPotionActive(Potion.nightVision),"Occupied amulet slot lost item/effect");server(()->{EntityPlayerMP p=player();check(p.getHeldItem().stackSize==1&&baubles.common.lib.PlayerHandler.getPlayerBaubles(p).getStackInSlot(0).getDisplayName().equals("LAN right-click amulet"),"Server overwrote equipped amulet");});pass("Right-clicking with an occupied amulet slot preserves both amulets and nightvision");phase=22;wait=20;return;}
  if(phase==22){finish(mc,false);}
 }catch(Throwable t){results.add("FAIL: phase "+phase+" :: "+t);IndustrialTechnology.log.error("Accessory graphical QA",t);ScreenShotHelper.saveScreenshot(mc.mcDataDir,"accessories-failure.png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());finish(mc,true);}}
 void finish(Minecraft mc,boolean failed){done=true;try{results.add("Failed: "+(failed?1:0));Files.write(new File(mc.mcDataDir,"accessories-client.txt").toPath(),results,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Accessory client report",e);}mc.displayGuiScreen(new GuiMainMenu());if(mc.theWorld!=null){mc.theWorld.sendQuittingDisconnectingPacket();mc.loadWorld(null);}mc.shutdown();}
}
